use std::fs

fn find(keys: Vec<int>, k: int) -> int {
    let mut i = 0
    while i < keys.len() as int {
        if keys[i] == k { return i }
        i += 1
    }
    -1
}

fn main() {
    let text = fs.read_to_string("/dev/stdin") ?? ""
    let lines: Vec<string> = text.lines().collect()
    let cap: int = lines[0].trim().parse::<int>() ?? 1
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    let mut li = 1
    while li < lines.len() as int {
        let parts: Vec<string> = lines[li].split_whitespace().collect()
        li += 1
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "put" {
            let k: int = parts[1].parse::<int>() ?? 0
            let v: int = parts[2].parse::<int>() ?? 0
            let idx = find(keys, k)
            if idx >= 0 {
                keys.remove(idx as usize)
                vals.remove(idx as usize)
            }
            keys.insert(0, k)
            vals.insert(0, v)
            if keys.len() as int > cap {
                let last = keys.len() - 1
                println("evict ${keys[last]}")
                keys.remove(last)
                vals.remove(last)
            }
        } else if cmd == "get" {
            let k: int = parts[1].parse::<int>() ?? 0
            let idx = find(keys, k)
            if idx < 0 {
                println("-1")
            } else {
                let v = vals[idx]
                keys.remove(idx as usize)
                vals.remove(idx as usize)
                keys.insert(0, k)
                vals.insert(0, v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = 0
                while i < keys.len() as int {
                    if i > 0 { out = out + " " }
                    out = out + "${keys[i]}"
                    i += 1
                }
                println(out)
            }
        }
    }
}

